package net.officefloor.hq.app.person;

import java.time.LocalDate;

/**
 * A person as the screen sees it. {@code grade} is the grade in force on the sheet's today; {@code retiredFrom}
 * is yyyy-mm-dd, null when not retired; {@code held} is whether they are on hold.
 */
public record PersonResponse(long id, String name, String grade, long version, String retiredFrom, boolean held) {

    public static PersonResponse from(Person person, LocalDate today) {
        return new PersonResponse(person.id(), person.name(), person.gradeOn(today), person.version(),
                person.retiredFrom() == null ? null : person.retiredFrom().toString(), person.held());
